package consumer

import (
  "context"
  "log/slog"

  "github.com/segmentio/kafka-go"
)

type Consumer struct {
  reader *kafka.Reader
  orders OrderService
}

func New(brokers []string, orders OrderService) *Consumer {
  return &Consumer{
    reader: kafka.NewReader(kafka.ReaderConfig{
      Brokers: brokers,
      GroupID: "order-worker",
      Topic:   "orders",
    }),
    orders: orders,
  }
}

func (c *Consumer) Run(ctx context.Context) error {
  for {
    m, err := c.reader.ReadMessage(ctx)
    if err != nil {
      return err
    }
    if err := c.orders.Handle(ctx, m.Value); err != nil {
      slog.Error("handle order", "offset", m.Offset, "err", err)
    }
  }
}

