func (c *Consumer) Run(ctx context.Context) error {
  for {
    m, err := c.reader.FetchMessage(ctx)
    if err != nil {
      return err
    }
    if err := c.orders.Handle(ctx, m.Value); err != nil {
      slog.Error("handle order", "partition", m.Partition, "offset", m.Offset, "err", err)
      continue
    }
    if err := c.reader.CommitMessages(ctx, m); err != nil {
      return err
    }
  }
}

func (s *OrderService) Handle(ctx context.Context, value []byte) error {
  var ev OrderEvent
  if err := json.Unmarshal(value, &ev); err != nil {
    return err
  }
  tx, err := s.db.BeginTx(ctx, nil)
  if err != nil {
    return err
  }
  defer tx.Rollback()

  res, err := tx.ExecContext(ctx,
    "INSERT INTO processed_events (event_id) VALUES ($1) ON CONFLICT DO NOTHING", ev.ID)
  if err != nil {
    return err
  }
  n, err := res.RowsAffected()
  if err != nil {
    return err
  }
  if n == 0 {
    return nil
  }
  if err := s.reserveStock(ctx, tx, ev); err != nil {
    return err
  }
  return tx.Commit()
}
